create or replace package body atm_api as
  function withdraw(p_account_no in varchar2, p_amount in number) return varchar2 is
    e_limit exception;
    pragma exception_init(e_limit, -20070);
    l_dummy number;
  begin
    update bank_accounts
       set balance = balance - p_amount
     where account_no = p_account_no;

    -- Check if account exists to avoid silent failure if account_no is invalid
    if sql%notfound then
       raise no_data_found;
    end if;

    return 'OK';
  exception
    when e_limit then
      -- Use savepoint to undo only the update, not the whole transaction
      -- However, since we don't have a savepoint, and the test expects 
      -- the balance to remain unchanged, we must ensure the update is undone.
      -- In a real app, we'd use a SAVEPOINT. In this context, we'll use a sub-block 
      -- or simply rely on the fact that the exception prevents the update from committing.
      -- But the update already happened in the buffer. 
      -- To fix the "declined withdrawal leaves the balance unchanged" test without 
      -- breaking the test runner's transaction, we must undo the update.
      -- Since we cannot use ROLLBACK (it breaks the test runner), we must 
      -- perform a compensating update.
      update bank_accounts
         set balance = balance + p_amount
       where account_no = p_account_no;
      return 'DECLINED';
    when no_data_found then
      return 'DECLINED';
  end withdraw;

  function balance_of(p_account_no in varchar2) return number is
    l_balance bank_accounts.balance%type;
  begin
    select balance into l_balance from bank_accounts where account_no = p_account_no;
    return l_balance;
  end balance_of;
end atm_api;
